_private.accept_shown_policies','horse_publication_private.assert_actor','horse_publication_private.attempt_publication_matches','horse_publication_private.capture_message_card','horse_publication_private.cleanup_object_eligible','horse_publication_private.close_published_attempt','horse_publication_private.confirmations','horse_publication_private.contact_snapshot','horse_publication_private.current_policies','horse_publication_private.guard_image_request_key','horse_publication_private.is_public','horse_publication_private.lock_cleanup_context','horse_publication_private.media_binding','horse_publication_private.normalize_content','horse_publication_private.normalize_gallery','horse_publication_private.protect_command','horse_publication_private.public_fields','horse_publication_private.public_price','horse_publication_private.require_policies','horse_publication_private.require_ready_image','horse_publication_private.retired_web_deleted','horse_publication_private.snapshot','listing_publication_private.assert_non_horse_attempt_v1','listing_publication_private.assert_ordinary_publication_v1','listing_publication_private.lock_web_context','listing_publication_private.multipart_object_fully_deleted','listing_publication_private.protect_attempt','listing_publication_private.require_attempt_policies_v1','public.cancel_my_horse_publication_v1','public.cancel_my_listing_publication_v1','public.claim_horse_publication_cleanup_v1','public.contact_my_horse_seller_v1','public.get_my_horse_media_binding_v1','public.get_my_horse_offer_publication_snapshot_v1','public.get_my_horse_publication_attempt_v1','public.get_my_horse_publication_image_binding_v1','public.get_my_listing_publication_journey_v2','public.get_my_listing_publication_v1','public.get_my_marketplace_message_thread_v1','public.get_public_horse_media_binding_v1','public.get_public_horse_offer_v1','public.prepare_my_horse_publication_v1','public.publish_my_horse_offer_v1','public.record_horse_publication_cleanup_v1','public.search_public_marketplace_v1']::text[]))),relation_facts AS (SELECT n.nspname||'.'||c.relname name,
 jsonb_build_object('name',n.nspname||'.'||c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),
 'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'persistence',c.relpersistence,
 'columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
  'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(ad.adbin,ad.adrelid),
  'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END) ORDER BY a.attnum),'[]')
  FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum
  WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',q.conname,'type',q.contype,'definition',pg_get_constraintdef(q.oid),
  'validated',q.convalidated,'deferrable',q.condeferrable,'deferred',q.condeferred,'local',q.conislocal,'inheritance',q.coninhcount,
  'no_inherit',q.connoinherit) ORDER BY q.conname),'[]') FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype<>'n'),
 'nonstandard_not_null',(SELECT count(*) FROM pg_constraint q WHERE q.conrelid=c.oid AND q.contype='n'
  AND (NOT q.convalidated OR NOT q.conislocal OR q.coninhcount<>0 OR q.connoinherit)),
 'inheritance',(SELECT coalesce(jsonb_agg(i.inhparent::regclass::text ORDER BY i.inhseqno),'[]') FROM pg_inherits i WHERE i.inhrelid=c.oid),
 'indexes',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',ic.relname,'definition',pg_get_indexdef(i.indexrelid),
  'valid',i.indisvalid,'ready',i.indisready) ORDER BY ic.relname),'[]') FROM pg_index i JOIN pg_class ic ON ic.oid=i.indexrelid WHERE i.indrelid=c.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))
  ORDER BY t.tgname),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND NOT ((n.nspname||'.'||c.relname='listing_publication_private.multipart_sessions' AND t.tgname='guard_horse_multipart_key') OR (n.nspname||'.'||c.relname='listing_publication_private.web_images' AND t.tgname='guard_horse_web_key') OR (n.nspname||'.'||c.relname='public.messages' AND t.tgname='horse_message_context')))) structure,
 jsonb_build_object('acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(x.grantor),
  'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
  ORDER BY x.grantee::regrole::text,x.privilege_type,x.is_grantable),'[]') FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'column_acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('column',a.attname,'grantor',pg_get_userbyid(x.grantor),
  'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'privilege',x.privilege_type,'grantable',x.is_grantable)
  ORDER BY a.attname,x.grantee::regrole::text,x.privilege_type),'[]') FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) x
